- How would you extend to support length-weighted queries for arbitrary weights per insertion?

## Why This Is Asked
Tests understanding of practical queue augmentations and min-tracking with guaranteed O(1) per operation.

## Key Concepts
- Min-tracking with stack-based queues
- Amortized analysis of transfers between stacks
- Edge-case handling for empty states and duplicates

## Code Example
```javascript
class MinQueue {
  constructor(){ this.inbox = []; this.outbox = [] }
  _push(stack, val){ const m = stack.length ? Math.min(val, stack[stack.length - 1].min) : val; stack.push({ val, min: m }) }
  enqueue(x){ this._push(this.inbox, x) }
  dequeue(){ if (!this.outbox.length){ while (this.inbox.length){ const el = this.inbox.pop(); const m = this.outbox.length ? Math.min(el.val, this.outbox[this.outbox.length - 1].min) : el.val; this.outbox.push({ val: el.val, min: m }) } }
    return this.outbox.pop().val }
  getMin(){ const mins = []; if (this.inbox.length) mins.push(this.inbox[this.inbox.length - 1].min); if (this.outbox.length) mins.push(this.outbox[this.outbox.length - 1].min); return mins.length ? Math.min(...mins) : undefined }
}
```

## Why This Is Asked
This question tests understanding of order statistics in dynamic multisets with duplicates and efficient prefix queries—skills fundamental to database indexing and ranking problems.

## Key Concepts
- **Balanced BST with per-node counts and subtree sizes** enables O(log n) operations
- **Handling duplicates via dupCount** avoids unnecessary node creation
- **getRank as a prefix-count query** is analogous to order statistics

## Code Example
```javascript
class Node {
  constructor(key) {
    this.key = key;
    this.dup = 1;
    this.left = null;
    this.right = null;
  }

  get size() {
    return this.dup + (this.left?.size ?? 0) + (this.right?.size ?? 0);
  }
}

class Treap {
  constructor() {
    this.root = null;
  }

  insert(key) {
    this.root = this._insert(this.root, key);
  }

  _insert(node, key) {
    if (!node) return new Node(key);
    if (key === node.key) {
      node.dup++;
    } else if (key < node.key) {
      node.left = this._insert(node.left, key);
    } else {
      node.right = this._insert(node.right, key);
    }
    return node;
  }

  erase(key) {
    this.root = this._erase(this.root, key);
  }

  _erase(node, key) {
    if (!node) return null;
    if (key === node.key) {
      node.dup--;
      if (node.dup === 0) return this._merge(node.left, node.right);
    } else if (key < node.key) {
      node.left = this._erase(node.left, key);
    } else {
      node.right = this._erase(node.right, key);
    }
    return node;
  }

  _merge(left, right) {
    if (!left || !right) return left ?? right;
    // Simplified: in a real Treap, merge by priority
    return this._bstMerge(left, right);
  }

  _bstMerge(left, right) {
    if (!left) return right;
    if (!right) return left;
    const node = left;
    node.right = this._bstMerge(node.right, right);
    return node;
  }

  getRank(v) {
    return this._getRank(this.root, v);
  }

  _getRank(node, v) {
    if (!node) return 0;
    if (v < node.key) {
      return this._getRank(node.left, v);
    }
    const leftSize = node.left?.size ?? 0;
    return leftSize + node.dup + this._getRank(node.right, v);
  }
}
```

